$lang['User-Agent figé partagé par de nombreuses IP'] = 'Frozen User-Agent shared across many IPs';
$lang['→ si un même User-Agent est vu au moins 20 fois avec au moins 90% d\'IP distinctes (quasiment jamais deux fois la même IP), les entrées sont marquées bots (marquage rétroactif) : signature typique d\'un pool de proxies résidentiels qui recycle une petite bibliothèque de User-Agents figés.'] = '→ if the same User-Agent is seen at least 20 times with at least 90% distinct IPs (almost never the same IP twice), the entries are flagged as bots (retroactive flagging): a typical signature of a residential proxy pool recycling a small library of frozen User-Agents.';
$lang['Bots d\'IA'] = 'AI bots';
